"""Hash the reviewed current manuscript and copy its qualified evidence summary."""
from pathlib import Path
import json,hashlib,re,subprocess,shutil
P=Path(__file__).resolve().parent;Q=P.parents[1]/'qualification/pi_pi_transfer_repair_20261101'
shutil.copyfile(Q/'qualification_summary.json',P/'data/screened_cid/qualification_summary.json')
def pages(name):return int(re.search(r'Pages:\s*(\d+)',subprocess.check_output(['pdfinfo',str(P/name)],text=True))[1])
manifest=dict(date='2026-11-01',revision='Final screened symmetry-augmented OO-CID; all seven pi states and thirteen n-pi controls within 0.5 eV',candidate_freeze_commit='2d59ab8',implementation_commit='81897cf',exact_acceleration_commit='e572d50',qualification_commit='358ae21',complete_logs_commit='7c5c7f9',electronic_compute_host='Verified Oracle for archived references and MAC-STUDIO for final development/qualification; never laptop',states=20,molecules=18,exposure='All twenty states exposed during final model development; no blind-validation claim',accuracy=json.loads((Q/'selected_summary.json').read_text()),analytic_hessian_molecules=3,analytic_hessian_states=4,main_pages=pages('main.pdf'),supporting_information_pages=pages('supporting_information.pdf'),main_figures=4,figures=len(list((P/'figures').glob('*.pdf'))),references=len(re.findall(r'\\bibitem',(P/'main.bbl').read_text())),bibliography_entries=len(re.findall(r'@\w+\{',(P/'references.bib').read_text())),runtime_state_checks=20,algebra_and_contract_regressions=10,verified_transferred_qualification_files=981,matching_public_sources=21,portable_examples=3,visual_review='All 12 main and 31 SI pages inspected in rendered contact sheets; final current figures and Jmol plate inspected individually. Updated main page 10 reviewed at full size. PDFs compile without overfull boxes or undefined references.',standalone_asset_rebuild='Current PNG and twenty-state TeX table reproduced byte-for-byte from bundled data and Jmol renders only; PDF geometry reviewed separately.',remaining_scientific_scope=['Broader independent frozen-label validation','Final-model excited equilibrium geometries and physical frequencies','Nonplanar/CT/Rydberg transferability and anchor sensitivity','All-inclusive final-model size-scaling comparisons'],sha256={})
allowed={'.tex','.bib','.py','.json','.csv','.tsv','.xyz','.pdf','.png','.svg','.md','.txt','.toml'}
for file in sorted(P.rglob('*')):
 if not file.is_file() or file==P/'MANIFEST.json' or 'tmp' in file.relative_to(P).parts or '__pycache__' in file.parts:continue
 if file.suffix in allowed or file.name=='.gitignore':manifest['sha256'][str(file.relative_to(P))]=hashlib.sha256(file.read_bytes()).hexdigest()
(P/'MANIFEST.json').write_text(json.dumps(manifest,indent=2)+'\n')
print({key:manifest[key] for key in ['main_pages','supporting_information_pages','main_figures','figures','references','bibliography_entries']})
